:root {
  --color-primary: #0066cc;
  --color-primary-dark: #004a99;
  --color-accent: #00d4ff;
  --color-accent-dark: #0099cc;
  --color-text: #1a1a1a;
  --color-text-light: #666666;
  --color-bg: #ffffff;
  --color-bg-alt: #f0f8ff;
  --color-border: #e0e0e0;
  --spacing-xs: 0.5rem;
  --spacing-sm: 1rem;
  --spacing-md: 1.5rem;
  --spacing-lg: 2rem;
  --spacing-xl: 3rem;
  --font-serif: Georgia, "Times New Roman", serif;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-mono: "Courier New", monospace;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-sans);
  color: var(--color-text);
  background-color: var(--color-bg);
  line-height: 1.6;
  font-size: 1rem;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 var(--spacing-md);
}

/* Header and Navigation */
.header {
  background-color: var(--color-bg);
  border-bottom: 1px solid var(--color-border);
  padding: var(--spacing-md) 0;
  position: sticky;
  top: 0;
  z-index: 100;
}

.logo {
  font-family: "Trebuchet MS", Verdana, sans-serif;
  font-weight: 800;
  font-size: clamp(1.25rem, 5vw, 1.5rem);
  color: var(--color-primary-dark);
  text-decoration: none;
  display: inline-block;
  letter-spacing: 0.02em;
  transform: rotate(-1deg);
  text-shadow: 2px 2px 0 var(--color-accent);
}

.logo:focus {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

.logo:hover {
  color: var(--color-accent-dark);
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: var(--spacing-sm);
}

h1 {
  font-size: clamp(2rem, 8vw, 3.5rem);
}

h2 {
  font-size: clamp(1.5rem, 5vw, 2.5rem);
}

h3 {
  font-size: clamp(1.25rem, 4vw, 1.75rem);
}

p {
  margin-bottom: var(--spacing-md);
  color: var(--color-text);
}

a {
  color: var(--color-primary-dark);
  text-decoration: none;
  font-weight: 500;
}

a:visited {
  color: var(--color-primary-dark);
}

a:hover {
  color: var(--color-accent-dark);
  text-decoration: underline;
}

a:focus {
  outline: 3px solid var(--color-primary);
  outline-offset: 2px;
}

/* Buttons */
button, .btn, input[type="submit"], input[type="button"] {
  display: inline-block;
  padding: var(--spacing-sm) var(--spacing-md);
  min-height: 44px;
  background-color: var(--color-primary-dark);
  color: #ffffff;
  font-size: 1rem;
  font-weight: 600;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  text-decoration: none;
  text-align: center;
  transition: background-color 0.2s ease, transform 0.1s ease, box-shadow 0.2s ease;
  font-family: var(--font-sans);
}

button:hover, .btn:hover, input[type="submit"]:hover, input[type="button"]:hover {
  background-color: var(--color-primary);
  transform: translateY(-2px);
  box-shadow: 0 4px 12px rgba(0, 74, 153, 0.3);
}

button:focus, .btn:focus, input[type="submit"]:focus, input[type="button"]:focus {
  outline: 3px solid var(--color-accent);
  outline-offset: 2px;
}

button:active, .btn:active, input[type="submit"]:active, input[type="button"]:active {
  transform: translateY(0);
}

.btn-secondary {
  background-color: var(--color-accent-dark);
  color: #ffffff;
}

.btn-secondary:hover {
  background-color: var(--color-accent);
}

/* Forms */
form {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
}

label {
  font-weight: 600;
  margin-bottom: var(--spacing-xs);
  display: block;
  color: var(--color-text);
}

input[type="text"],
input[type="email"],
input[type="tel"],
input[type="number"],
textarea,
select {
  width: 100%;
  padding: 0.75rem;
  border: 2px solid var(--color-border);
  border-radius: 6px;
  font-family: var(--font-sans);
  font-size: 1rem;
  transition: border-color 0.2s ease;
  min-height: 44px;
}

input:focus,
textarea:focus,
select:focus {
  outline: none;
  border-color: var(--color-primary-dark);
  box-shadow: 0 0 0 3px rgba(0, 102, 204, 0.1);
}

/* Footer */
.footer {
  background-color: var(--color-bg-alt);
  color: var(--color-text);
  padding: var(--spacing-lg) 0;
  margin-top: var(--spacing-xl);
  border-top: 1px solid var(--color-border);
  text-align: center;
}

.footer p {
  margin-bottom: var(--spacing-sm);
  font-size: 0.9rem;
}

.footer a {
  color: var(--color-primary-dark);
}

.footer a:hover {
  color: var(--color-accent-dark);
}

/* Grid and Layout Helpers */
.grid {
  display: grid;
  gap: var(--spacing-lg);
  width: 100%;
}

.grid-2 {
  grid-template-columns: 1fr;
}

.grid-3 {
  grid-template-columns: 1fr;
}

.card {
  background-color: var(--color-bg-alt);
  padding: var(--spacing-md);
  border-radius: 8px;
  border: 1px solid var(--color-border);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.1);
}

/* Mobile-First Responsive Design */
@media (max-width: 600px) {
  :root {
    --spacing-lg: 1.5rem;
    --spacing-xl: 2rem;
  }

  .container {
    padding: 0 var(--spacing-md);
  }

  .grid-2 {
    grid-template-columns: 1fr;
  }

  .grid-3 {
    grid-template-columns: 1fr;
  }

  h1 {
    font-size: 2rem;
  }

  h2 {
    font-size: 1.5rem;
  }

  .logo {
    font-size: 1.25rem;
  }
}

/* Desktop Responsive Design */
@media (min-width: 601px) {
  .grid-2 {
    grid-template-columns: repeat(2, 1fr);
  }

  .grid-3 {
    grid-template-columns: repeat(3, 1fr);
  }
}

pages.css:
.index-hero {
  background: linear-gradient(135deg, var(--color-primary-dark) 0%, var(--color-primary) 100%);
  color: #ffffff;
  padding: var(--spacing-xl) var(--spacing-md);
  text-align: center;
}

.index-hero h1 {
  color: #ffffff;
  margin-bottom: var(--spacing-md);
}

.index-hero-subtitle {
  color: #ffffff;
  font-size: 1.1rem;
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.index-features {
  padding: var(--spacing-xl) var(--spacing-md);
  background-color: var(--color-bg);
}

.index-features h2 {
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

.index-feature-card {
  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.index-feature-card:hover {
  transform: translateY(-8px);
  box-shadow: 0 12px 24px rgba(0, 74, 153, 0.15);
}

.index-feature-icon {
  font-size: 3rem;
  margin-bottom: var(--spacing-md);
  display: block;
}

.index-feature-card h3 {
  margin-bottom: var(--spacing-sm);
  color: var(--color-primary-dark);
}

.index-feature-card p {
  color: var(--color-text-light);
  font-size: 0.95rem;
}

.index-screenshots {
  padding: var(--spacing-xl) var(--spacing-md);
  background-color: var(--color-bg-alt);
}

.index-screenshots h2 {
  text-align: center;
  margin-bottom: var(--spacing-xl);
}

.index-screenshots-gallery {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-lg);
  align-items: center;
  justify-content: center;
}

.index-screenshot-item {
  text-align: center;
  margin: 0;
}

.index-screenshot-item img {
  max-width: 100%;
  height: auto;
  border-radius: 12px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  border: 2px solid var(--color-border);
}

.index-screenshot-item figcaption {
  margin-top: var(--spacing-md);
  font-weight: 600;
  color: var(--color-primary-dark);
}

.index-testimonial {
  padding: var(--spacing-xl) var(--spacing-md);
  background-color: var(--color-bg);
  text-align: center;
}

.index-testimonial h2 {
  margin-bottom: var(--spacing-lg);
}

.index-testimonial-quote {
  max-width: 700px;
  margin: 0 auto;
  font-size: 1.1rem;
  font-style: italic;
  color: var(--color-text-light);
  border-left: 4px solid var(--color-accent-dark);
  padding-left: var(--spacing-md);
}

.index-testimonial-quote p {
  margin-bottom: var(--spacing-md);
  color: var(--color-text-light);
}

.index-testimonial-author {
  display: block;
  font-weight: 600;
  color: var(--color-primary-dark);
  font-style: normal;
}

.index-download {
  padding: var(--spacing-xl) var(--spacing-md);
  background: linear-gradient(135deg, var(--color-accent-dark) 0%, var(--color-accent) 100%);
  color: #ffffff;
  text-align: center;
}

.index-download h2 {
  color: #ffffff;
  margin-bottom: var(--spacing-md);
}

.index-download-subtitle {
  color: #ffffff;
  font-size: 1.05rem;
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.index-download-buttons {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
  max-width: 400px;
  margin: 0 auto var(--spacing-lg);
}

.index-download-buttons .btn {
  background-color: #ffffff;
  color: var(--color-primary-dark);
  font-weight: 700;
}

.index-download-buttons .btn:hover {
  background-color: rgba(255, 255, 255, 0.9);
}

.index-download-buttons .btn-secondary {
  background-color: rgba(255, 255, 255, 0.2);
  color: #ffffff;
  border: 2px solid #ffffff;
}

.index-download-buttons .btn-secondary:hover {
  background-color: rgba(255, 255, 255, 0.3);
}

.index-download-note {
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.9rem;
  margin: 0;
}

/* Mobile Responsive Design */
@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .index-hero-subtitle {
    font-size: 1rem;
  }

  .index-features {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .index-features-grid {
    gap: var(--spacing-md);
  }

  .index-feature-icon {
    font-size: 2.5rem;
  }

  .index-screenshots {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .index-screenshot-item img {
    max-width: 240px;
  }

  .index-testimonial {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .index-testimonial-quote {
    font-size: 1rem;
    padding-left: var(--spacing-md);
  }

  .index-download {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .index-download-buttons {
    gap: var(--spacing-sm);
  }

  .index-download-buttons .btn,
  .index-download-buttons .btn-secondary {
    padding: var(--spacing-sm) var(--spacing-md);
    font-size: 0.95rem;
  }
}

/* Desktop Responsive Design */
@media (min-width: 601px) {
  .index-screenshots-gallery {
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
  }

  .index-screenshot-item {
    flex: 0 1 calc(33.333% - var(--spacing-lg));
    max-width: 320px;
  }

  .index-download-buttons {
    flex-direction: row;
    max-width: 600px;
    gap: var(--spacing-lg);
  }

  .index-download-buttons .btn {
    flex: 1;
  }

  .index-download-buttons .btn-secondary {
    flex: 1;
  }
}

