.index-download {
  padding: var(--spacing-xl) var(--spacing-md);
  background: linear-gradient(135deg, var(--color-accent-dark) 0%, var(--color-accent) 100%);
  color: #ffffff;
  text-align: center;
}

.index-download h2 {
  color: #ffffff;
  margin-bottom: var(--spacing-md);
}

.index-download-subtitle {
  color: #ffffff;
  font-size: 1.05rem;
  margin-bottom: var(--spacing-lg);
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.index-download-buttons {
  display: flex;
  flex-direction: column;
  gap: var(--spacing-md);
  max-width: 400px;
  margin: 0 auto var(--spacing-lg);
}

.index-download-buttons .btn {
  background-color: #ffffff;
  color: var(--color-primary-dark);
  font-weight: 700;
}

.index-download-buttons .btn:hover {
  background-color: rgba(255, 255, 255, 0.9);
}

.index-download-buttons .btn-secondary {
  background-color: rgba(255, 255, 255, 0.2);
  color: #ffffff;
  border: 2px solid #ffffff;
}

.index-download-buttons .btn-secondary:hover {
  background-color: rgba(255, 255, 255, 0.3);
}

.index-download-note {
  color: rgba(255, 255, 255, 0.9);
  font-size: 0.9rem;
  margin: 0;
}

/* Mobile Responsive Design */
@media (max-width: 600px) {
  .index-hero {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .index-hero-subtitle {
    font-size: 1rem;
  }

  .index-features {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .index-features-grid {
    gap: var(--spacing-md);
  }

  .index-feature-icon {
    font-size: 2.5rem;
  }

  .index-screenshots {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .index-screenshot-item img {
    max-width: 240px;
  }

  .index-testimonial {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .index-testimonial-quote {
    font-size: 1rem;
    padding-left: var(--spacing-md);
  }

  .index-download {
    padding: var(--spacing-lg) var(--spacing-md);
  }

  .index-download-buttons {
    gap: var(--spacing-sm);
  }

  .index-download-buttons .btn,
  .index-download-buttons .btn-secondary {
    padding: var(--spacing-sm) var(--spacing-md);
    font-size: 0.95rem;
  }
}

/* Desktop Responsive Design */
@media (min-width: 601px) {
  .index-screenshots-gallery {
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
  }

  .index-screenshot-item {
    flex: 0 1 calc(33.333% - var(--spacing-lg));
    max-width: 320px;
  }

  .index-download-buttons {
    flex-direction: row;
    max-width: 600px;
    gap: var(--spacing-lg);
  }

  .index-download-buttons .btn {
    flex: 1;
  }

  .index-download-buttons .btn-secondary {
    flex: 1;
  }
}
